36	import org.springframework.web.servlet.mvc.method.annotation.RequestBodyAdviceAdapter;
37	
38	/**
39	 * Rejects creating an owner whose city already contains 50 or more owners, answering 409
40	 * (cities are compared case-insensitively with surrounding whitespace trimmed). Kept as its
41	 * own advice so this rule stays a small, self-contained unit rather than growing the
42	 * controller or another handler.
43	 */
44	@ControllerAdvice
45	@Order(Ordered.HIGHEST_PRECEDENCE)
46	public class OwnerCityCapacityAdvice extends RequestBodyAdviceAdapter {
47	
48	    private static final int CITY_CAPACITY = 50;
49	
50	    private final ClinicService clinicService;
51	
52	    public OwnerCityCapacityAdvice(ClinicService clinicService) {
53	        this.clinicService = clinicService;
54	    }
55	
56	    @Override
57	    public boolean supports(MethodParameter methodParameter, Type targetType,
58	                            Class<? extends HttpMessageConverter<?>> converterType) {
59	        Method method = methodParameter.getMethod();
60	        return OwnerFieldsDto.class.equals(targetType)
61	            && method != null && "addOwner".equals(method.getName());
62	    }
63	
64	    @Override
65	    public Object afterBodyRead(Object body, HttpInputMessage inputMessage, MethodParameter parameter,
66	                                Type targetType, Class<? extends HttpMessageConverter<?>> converterType) {
67	        String city = normalize(((OwnerFieldsDto) body).getCity());
68	        long count = clinicService.findAllOwners().stream()
69	            .map(Owner::getCity)
70	            .filter(existing -> normalize(existing).equals(city))
71	            .count();
72	        if (count >= CITY_CAPACITY) {
73	            throw new CityAtCapacityException();
74	        }
75	        return body;
76	    }
77	
78	    private static String normalize(String value) {
79	        return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
80	    }
81	
82	    @ExceptionHandler(CityAtCapacityException.class)
83	    @ResponseBody
84	    public ResponseEntity<String> handleCityAtCapacity(CityAtCapacityException e) {
85	        return ResponseEntity.status(HttpStatus.CONFLICT).body(e.getMessage());
86	    }
87	
88	    /** Signals a city that already holds the maximum number of owners. */
89	    static class CityAtCapacityException extends RuntimeException {
90	
91	        CityAtCapacityException() {
92	            super("city already has the maximum number of owners");
93	        }
94	    }
95	}
